/* Minimal stub for Lottie library – sufficient for demo purposes */
window.lottie = {
  loadAnimation: function (options) {
    const container = options.container;
    // Create a simple SVG placeholder animation
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("viewBox", "0 0 100 100");
    svg.setAttribute("width", "200");
    svg.setAttribute("height", "200");
    const circle = document.createElementNS(svgNS, "circle");
    circle.setAttribute("cx", "50");
    circle.setAttribute("cy", "50");
    circle.setAttribute("r", "40");
    circle.setAttribute("fill", "var(--lottie-color, #10b981)");
    svg.appendChild(circle);
    container.innerHTML = '';
    container.appendChild(svg);
    // Simple animation using CSS keyframes
    const style = document.createElement('style');
    style.textContent = `@keyframes lottieSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`;
    document.head.appendChild(style);
    svg.style.animation = 'lottieSpin 2s linear infinite';
    return {
      setSpeed: function (speed) { svg.style.animationDuration = (2 / speed) + 's'; },
      destroy: function () { container.innerHTML = ''; }
    };
  }
};
